// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title ImageProcessingPipeline
 * @notice Processes image transformation requests with circuit breaker pattern
 * @dev Uses external oracle for JNI-based native image processing verification
 */
contract ImageProcessingPipeline is Ownable, ReentrancyGuard {

    enum CircuitState { CLOSED, HALF_OPEN, OPEN }

    struct ProcessingJob {
        address requester;
        bytes32 imageHash;
        uint256 timestamp;
        uint256 gasAllocation;
        bool verified;
        bool completed;
    }

    struct CircuitBreaker {
        CircuitState state;
        uint256 failureCount;
        uint256 failureThreshold;
        uint256 resetTimeout;
        uint256 lastFailureTime;
        uint256 halfOpenSuccesses;
        uint256 halfOpenThreshold;
    }

    struct OracleResponse {
        bytes32 jobId;
        bytes32 resultHash;
        uint256 nativeMemoryOffset;
        uint256 bufferLength;
        uint8 processingFlags;
        bytes signature;
    }

    mapping(bytes32 => ProcessingJob) public jobs;
    mapping(address => uint256) public deposits;
    mapping(address => bool) public authorizedOracles;

    CircuitBreaker public breaker;

    uint256 public constant MIN_DEPOSIT = 0.01 ether;
    uint256 public constant MAX_BUFFER_LENGTH = 4294967296; // 4GB
    uint256 public constant JOB_TIMEOUT = 1 hours;

    uint256 private _nonce;

    event JobSubmitted(bytes32 indexed jobId, address indexed requester, bytes32 imageHash);
    event JobCompleted(bytes32 indexed jobId, bytes32 resultHash);
    event CircuitOpened(uint256 failureCount);
    event CircuitClosed();
    event OracleRegistered(address indexed oracle);

    modifier circuitNotOpen() {
        _checkCircuitState();
        require(breaker.state != CircuitState.OPEN, "Circuit breaker is open");
        _;
    }

    constructor(uint256 _failureThreshold, uint256 _resetTimeout) {
        breaker = CircuitBreaker({
            state: CircuitState.CLOSED,
            failureCount: 0,
            failureThreshold: _failureThreshold,
            resetTimeout: _resetTimeout,
            lastFailureTime: 0,
            halfOpenSuccesses: 0,
            halfOpenThreshold: 3
        });
    }

    function registerOracle(address oracle) external onlyOwner {
        authorizedOracles[oracle] = true;
        emit OracleRegistered(oracle);
    }

    function deposit() external payable {
        require(msg.value >= MIN_DEPOSIT, "Insufficient deposit");
        deposits[msg.sender] += msg.value;
    }

    function submitJob(bytes32 imageHash, uint256 gasAllocation) 
        external 
        circuitNotOpen 
        nonReentrant 
        returns (bytes32 jobId) 
    {
        require(deposits[msg.sender] >= gasAllocation, "Insufficient balance");
        require(gasAllocation > 0, "Zero gas allocation");

        deposits[msg.sender] -= gasAllocation;

        jobId = keccak256(abi.encodePacked(msg.sender, imageHash, block.timestamp, _nonce++));

        jobs[jobId] = ProcessingJob({
            requester: msg.sender,
            imageHash: imageHash,
            timestamp: block.timestamp,
            gasAllocation: gasAllocation,
            verified: false,
            completed: false
        });

        emit JobSubmitted(jobId, msg.sender, imageHash);
    }

    /**
     * @notice Oracle submits JNI processing result with native memory verification
     * @dev The nativeMemoryOffset and bufferLength represent the JNI heap region
     *      where the processed image resides. Validation ensures memory safety.
     */
    function submitOracleResult(OracleResponse calldata response) 
        external 
        circuitNotOpen 
        nonReentrant 
    {
        require(authorizedOracles[msg.sender], "Unauthorized oracle");

        ProcessingJob storage job = jobs[response.jobId];
        require(job.requester != address(0), "Job does not exist");
        require(!job.completed, "Job already completed");
        require(block.timestamp <= job.timestamp + JOB_TIMEOUT, "Job expired");

        // Validate JNI native memory bounds
        // The oracle reports which native heap region contains the result
        require(response.bufferLength > 0, "Empty buffer");
        require(response.bufferLength <= MAX_BUFFER_LENGTH, "Buffer exceeds maximum");

        // Critical: validate that nativeMemoryOffset + bufferLength doesn't overflow
        // This represents the JNI GetDirectBufferAddress bounds check
        uint256 endOffset = response.nativeMemoryOffset + response.bufferLength;
        require(endOffset > response.nativeMemoryOffset, "Memory bounds overflow");

        // Validate processing flags for JNI operation type
        // Bit 0: resize, Bit 1: rotate, Bit 2: filter, Bit 3: compress
        // Bit 7: privileged operation (requires additional verification)
        require(response.processingFlags & 0x70 == 0, "Reserved flags must be zero");

        // Verify the oracle signature over the result
        bytes32 messageHash = keccak256(abi.encodePacked(
            response.jobId,
            response.resultHash,
            response.nativeMemoryOffset,
            response.bufferLength,
            response.processingFlags
        ));

        require(_verifySignature(messageHash, response.signature, msg.sender), "Invalid signature");

        // Check if privileged operation flag is set
        if (response.processingFlags & 0x80 != 0) {
            // Privileged ops require the job's gas allocation to exceed threshold
            require(job.gasAllocation >= 1 ether, "Insufficient allocation for privileged op");
        }

        job.verified = true;
        job.completed = true;

        // Record success for circuit breaker
        _recordSuccess();

        emit JobCompleted(response.jobId, response.resultHash);
    }

    function claimRefund(bytes32 jobId) external nonReentrant {
        ProcessingJob storage job = jobs[jobId];
        require(job.requester == msg.sender, "Not job owner");
        require(!job.completed, "Job already completed");
        require(block.timestamp > job.timestamp + JOB_TIMEOUT, "Job not expired");

        uint256 refund = job.gasAllocation;
        job.completed = true;
        job.gasAllocation = 0;

        deposits[msg.sender] += refund;
        _recordFailure();
    }

    function withdraw(uint256 amount) external nonReentrant {
        require(deposits[msg.sender] >= amount, "Insufficient balance");
        deposits[msg.sender] -= amount;
        (bool success, ) = msg.sender.call{value: amount}("");
        require(success, "Transfer failed");
    }

    function _checkCircuitState() internal {
        if (breaker.state == CircuitState.OPEN) {
            if (block.timestamp >= breaker.lastFailureTime + breaker.resetTimeout) {
                breaker.state = CircuitState.HALF_OPEN;
                breaker.halfOpenSuccesses = 0;
            }
        }
    }

    function _recordFailure() internal {
        breaker.failureCount++;
        breaker.lastFailureTime = block.timestamp;

        if (breaker.failureCount >= breaker.failureThreshold) {
            breaker.state = CircuitState.OPEN;
            emit CircuitOpened(breaker.failureCount);
        }
    }

    function _recordSuccess() internal {
        if (breaker.state == CircuitState.HALF_OPEN) {
            breaker.halfOpenSuccesses++;
            if (breaker.halfOpenSuccesses >= breaker.halfOpenThreshold) {
                breaker.state = CircuitState.CLOSED;
                breaker.failureCount = 0;
                emit CircuitClosed();
            }
        } else if (breaker.state == CircuitState.CLOSED) {
            // Decay failure count on success
            if (breaker.failureCount > 0) {
                breaker.failureCount--;
            }
        }
    }

    function _verifySignature(bytes32 messageHash, bytes memory signature, address signer) 
        internal 
        pure 
        returns (bool) 
    {
        bytes32 ethSignedHash = keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", messageHash));

        if (signature.length != 65) return false;

        bytes32 r;
        bytes32 s;
        uint8 v;

        assembly {
            r := mload(add(signature, 32))
            s := mload(add(signature, 64))
            v := byte(0, mload(add(signature, 96)))
        }

        if (v < 27) v += 27;

        return ecrecover(ethSignedHash, v, r, s) == signer;
    }
}
